function simpleHashImpl(key, arraySize) {
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = (hash * 31 + key.charCodeAt(i)) % arraySize;
  }
  return hash;
}

function verifyDeterminism(key, arraySize, trials) {
  const first = simpleHashImpl(key, arraySize);
  for (let i = 1; i < trials; i++) {
    if (simpleHashImpl(key, arraySize) !== first) return false;
  }
  return true;
}

function measureDistribution(keys, arraySize) {
  const bucketCounts = new Array(arraySize).fill(0);
  for (const key of keys) {
    bucketCounts[simpleHashImpl(key, arraySize)]++;
  }
  const maxBucketSize = Math.max(...bucketCounts);
  const isReasonablyUniform = maxBucketSize <= Math.ceil(keys.length / arraySize) + 2;
  return { bucketCounts, maxBucketSize, isReasonablyUniform };
}

