class GradeTracker {
  constructor() {
    this.grades = new Map();
  }
  setGrade(student, score) {
    this.grades.set(student, score);
  }
  getGrade(student) {
    return this.grades.has(student) ? this.grades.get(student) : 'NOT_RECORDED';
  }
  removeStudent(student) {
    this.grades.delete(student);
  }
  getGradeDistribution() {
    const dist = new Map();
    for (const score of this.grades.values()) {
      dist.set(score, (dist.get(score) || 0) + 1);
    }
    return dist;
  }
  getStudentsInOrder() {
    return [...this.grades.keys()];
  }
}

