function groupByFingerprint(items, computeKey) {
  const map = new Map();
  for (const item of items) {
    const key = computeKey(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  }
  return [...map.values()];
}

function anagramFingerprint(s) {
  const count = new Array(26).fill(0);
  for (const c of s) count[c.charCodeAt(0) - 97]++;
  return count.join('#');
}

function digitSumFingerprint(n) {
  return String(n).split('').reduce((s, d) => s + Number(d), 0);
}

