function topKFrequentSort(nums, k) {
  const freq = new Map();
  for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
  return [...freq.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, k)
    .map(([num]) => num);
}

function topKFrequentBucket(nums, k) {
  const freq = new Map();
  for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
  const buckets = new Array(nums.length + 1).fill(null).map(() => []);
  for (const [num, count] of freq) {
    buckets[count].push(num);
  }
  const result = [];
  for (let i = buckets.length - 1; i >= 1 && result.length < k; i--) {
    result.push(...buckets[i]);
  }
  return result.slice(0, k);
}

function benchmarkTopK(size, k) {
  const nums = Array.from({length: size}, () => Math.floor(Math.random() * (size / 10)));
  const t1 = Date.now();
  topKFrequentSort(nums, k);
  const sortMs = Date.now() - t1;
  const t2 = Date.now();
  topKFrequentBucket(nums, k);
  const bucketMs = Date.now() - t2;
  return { sortMs, bucketMs };
}

