function encodeImpl(strs) {
  return strs.map(s => `${s.length}#${s}`).join('');
}

function decodeImpl(s) {
  const result = [];
  let i = 0;
  while (i < s.length) {
    let j = i;
    while (s[j] !== '#') j++;
    const len = Number(s.slice(i, j));
    const str = s.slice(j + 1, j + 1 + len);
    result.push(str);
    i = j + 1 + len;
  }
  return result;
}

function roundTripTest(strs) {
  const decoded = decodeImpl(encodeImpl(strs));
  return JSON.stringify(decoded) === JSON.stringify(strs);
}

